import{_ as a,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"Amazon A+模块简报与图文交付","description":"","frontmatter":{"id":"P12","title":"Amazon A+模块简报与图文交付","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting","ecommerce-image-toolkit"],"order":112},"headers":[],"relativePath":"prompts/P12.md","filePath":"prompts/P12.md"}'),l={name:"prompts/P12.md"};function t(i,s,o,c,r,m){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="p12-amazon-a-模块简报与图文交付" tabindex="-1">P12 Amazon A+模块简报与图文交付 <a class="header-anchor" href="#p12-amazon-a-模块简报与图文交付" aria-label="Permalink to &quot;P12 Amazon A+模块简报与图文交付&quot;">​</a></h1><p>类型：模块规划。替换项目：当前可用模块、尺寸提示、真实素材、准确文案。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="./../ecommerce/amazon-a-plus">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请为Amazon US商品制作A+模块内容方案。本次以当前账户实际可用的模块为准，不假设Premium能力。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入还包括我提供的模块名称、图片槽位尺寸和文字字段；未提供的项目写待填，先交内容规划。</span></span>
<span class="line"><span>内容单元：商品与使用场景；开盖／隔板；真实外尺寸；操作步骤；发货内容。按照实际模块合并或拆开，不强凑固定模块数。</span></span>
<span class="line"><span>每个模块输出：模块用途、买家问题、所需素材、图片简报、准确英文标题与正文、原生文字字段、导出要求、核对项。</span></span>
<span class="line"><span>较长说明优先用支持的文字字段；不得把长文直接嵌入一张缩小后读不清的图。</span></span>
<span class="line"><span>没有其他型号和参数时，不制作虚假对比表；没有品牌历史时，不编造品牌故事。</span></span>
<span class="line"><span>准确文字中可以描述“removable divider”，但不出现waterproof、food-safe等未知声明。</span></span>
<span class="line"><span>最后给桌面／手机预览检查清单：裁切、字号、顺序、参数、配件、模块尺寸和文字准确性。</span></span>
<span class="line"><span>未实际进入编辑器时，只写模块内容方案完成，不写上线或审核通过。</span></span>
<span class="line"><span>本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const u=a(l,[["render",t]]);export{_ as __pageData,u as default};
